import{_ as t,o as d,c as o,a0 as c}from"./chunks/framework.Bmhw_dvp.js";const p=JSON.parse('{"title":"房间同步逻辑","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/sync.md","filePath":"advanced/sync.md","lastUpdated":1793354072000}'),a={name:"advanced/sync.md"};function r(s,e,i,n,l,h){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="房间同步逻辑" tabindex="-1">房间同步逻辑 <a class="header-anchor" href="#房间同步逻辑" aria-label="Permalink to &quot;房间同步逻辑&quot;">​</a></h1><p>房间实时同步全部走 Socket.IO。连接建立前经 JWT 鉴权中间件 <code>io.use</code>，token 无效直接拒绝握手，WebSocket 与 REST 共用同一套身份。客户端只维持一个全局单例连接（<code>transports: [&#39;websocket&#39;,&#39;polling&#39;]</code>、<code>withCredentials: true</code>），引用计数归零后延迟 100ms 断开。</p><h2 id="房间数据结构与权威副本" tabindex="-1">房间数据结构与权威副本 <a class="header-anchor" href="#房间数据结构与权威副本" aria-label="Permalink to &quot;房间数据结构与权威副本&quot;">​</a></h2><p>服务器持有房间状态的权威副本，房主和观众都从它取值，分层与<a href="/advanced/index">架构总览</a>一致。</p><ul><li><strong>运行时副本</strong> <code>RoomRuntimeState</code>（内存 Map）：影片列表、当前影片、播放状态，以及房主最近一次 <code>subtitle-update</code> 的字幕缓存。字幕缓存只用于给中途加入的观众补发，不写库。</li><li><strong>播放记忆</strong> <code>PlaybackMemoryService</code>：内存缓存 + <code>PlaybackState</code> 表节流落盘（状态 2s、心跳 10s）。房主刷新后凭 <code>currentMovieId</code> 匹配同一影片恢复播放。每 30s 清理陈旧缓存（房主离线且最后更新超 10 分钟）。</li><li><strong>持久化实体</strong>：<code>Room</code> 与一对一关联的 <code>PlaybackState</code>。<code>Room</code> 字段含 roomId（8 位 nanoid）、密码（bcrypt cost 10）、<code>mode</code>、<code>shareMethod</code>、<code>streamKey</code>、审批开关、禁言与房管的 JSON 数组，以及 <code>lastAccessedAt</code>。</li></ul><p>房主在线需同时满足：<code>hostSocketId</code> 不为空，且该 id 仍在 <code>io.sockets.sockets</code> 中（<code>isHostOnline()</code>）。只看前者会在后端重启后误判——旧 socket id 仍留在数据库里。</p><h2 id="关键事件" tabindex="-1">关键事件 <a class="header-anchor" href="#关键事件" aria-label="Permalink to &quot;关键事件&quot;">​</a></h2><p>标注 ack 的事件由客户端等待回调结果。</p><table tabindex="0"><thead><tr><th>事件</th><th>方向</th><th>说明</th></tr></thead><tbody><tr><td><code>create-room</code> / <code>close-room</code> / <code>host-leave</code></td><td>C→S (ack)</td><td>房间生命周期。<code>host-leave</code> 为暂离，不关房</td></tr><tr><td><code>register-host</code></td><td>C→S (ack)</td><td>房主注册或重连，返回 mode、shareMethod、streamKey 与推算后的 playback</td></tr><tr><td><code>request-join</code></td><td>C→S (ack)</td><td><code>bcrypt.compare</code> 校验密码（root 免密）与人数上限</td></tr><tr><td><code>join-request</code> / <code>approve-join</code> / <code>reject-join</code></td><td>审批流</td><td>需审批时转发给房主；批准后 userId 写入 <code>approvedViewers</code>，此后永久免审批</td></tr><tr><td><code>play-movie</code> / <code>movie-list</code> / <code>current-movie</code></td><td>影片</td><td>权限由 <code>manageMovie</code> 矩阵控制；切换立即广播</td></tr><tr><td><code>watch-together-state</code></td><td>房主→S→成员</td><td>完整状态 <code>{state, diff, seq}</code>；先持久化再广播</td></tr><tr><td><code>watch-together-control</code></td><td>房主→S→成员</td><td><code>play/pause/seek/rate</code> 离散操作；<strong>先广播（亚 500ms）后持久化</strong></td></tr><tr><td><code>host-heartbeat</code></td><td>房主→S→成员</td><td>每 5s 一次 <code>{currentTime, isPlaying, playbackRate}</code></td></tr><tr><td><code>sync-heartbeat</code></td><td>S→成员</td><td>统一心跳，<code>source: &#39;host&#39; | &#39;server&#39;</code> 区分来源</td></tr><tr><td><code>seek-request</code> / <code>pause-request</code> / <code>play-request</code> (+<code>*-response</code>)</td><td>控制权申请</td><td>见「控制权申请」</td></tr><tr><td><code>subtitle-update</code> / <code>subtitle-request</code> / <code>track-change</code></td><td>字幕/轨道</td><td>转发完整 tracks 与 cues 并缓存；类型分 <code>danmaku</code> / <code>subtitle</code></td></tr><tr><td><code>send-danmaku</code> / <code>send-comment</code> / <code>annotation-stroke</code></td><td>弹幕/评论/批注</td><td>持久化后广播；发送前校验在房与禁言状态</td></tr></tbody></table><p>处理器按域注册在后端的 <code>internal/room/*_handlers.go</code>（<code>sc.On(...)</code>），ack 统一为 <code>{ success, message?, code?, data? }</code>。</p><p>两个 watch-together 事件的落盘与广播顺序相反，且是有意如此：<code>watch-together-state</code> 携带完整快照属权威数据，先写库再广播；<code>watch-together-control</code> 只是暂停、跳转这类离散操作，先广播保证即时性，再写库。改这两处前先看 handler 注释。</p><h2 id="房主同步模型" tabindex="-1">房主同步模型 <a class="header-anchor" href="#房主同步模型" aria-label="Permalink to &quot;房主同步模型&quot;">​</a></h2><p>房主是唯一同步源，观众进度一律以房主播放器为准。链路为「video 事件 → 防抖/节流 → 差分广播 → 服务器持久化并转发 → 观众对齐」：</p><ol><li><strong>事件绑定</strong>（<code>useVideoEventBindings.ts</code>）：<code>play/pause</code> 防抖 100ms、<code>seeked</code> 防抖 300ms、<code>ratechange</code> 立即触发。<code>timeupdate</code> 不广播，进度全走心跳。</li><li><strong>差分广播</strong>（<code>useHostBroadcast.ts</code> + <code>state-merge.ts</code>）：先与上次状态浅比较，<code>currentTime</code> 相差 ≤2s 视为等价直接跳过；否则 <code>computeStateDiff</code> 生成增量并 <code>emit(&#39;watch-together-state&#39;, {state, diff, seq})</code>，seq 房主侧自增。</li><li><strong>心跳</strong>（<code>useHostHeartbeat.ts</code>）：每 <strong>5s</strong> 一次 <code>host-heartbeat</code>。事件抑制期内（观众 seek 会回灌房主 video 事件）改发带 <code>suppressed: true</code> 的存活心跳，观众只重置离线计时、不校正进度。抑制用计数式租约管理，5 分钟自动过期。</li><li><strong>服务端处理</strong>：校验 isRoomHost 与房间模式 → 写播放记忆 → 转发。<code>watch-together-control</code> 三条规则：pause 把 <code>currentTime</code> 凝固为推算值；seek 只改时间不改 <code>isPlaying</code>（避免 seek 后暂停抖动）；rate 先推算当前进度再改倍速。</li></ol><h2 id="观众端对齐算法" tabindex="-1">观众端对齐算法 <a class="header-anchor" href="#观众端对齐算法" aria-label="Permalink to &quot;观众端对齐算法&quot;">​</a></h2><p>状态事件与心跳分两条通路，互不干扰。</p><ul><li><strong>状态事件</strong>（<code>useViewerStateSync.ts</code>）只管离散字段：<code>sourceUrl</code> 变了才重建播放流（以 <code>state.currentTime</code> 为起点）；<code>isPlaying</code> 变了才 play/pause；<code>playbackRate</code> 变了才设倍速。<code>currentTime</code> 不随状态事件设置。seq 跳号（<code>payload.seq &gt; lastSeq + 1</code>）即丢弃增量并请求全量自愈。</li><li><strong>心跳驱动进度</strong>（<code>useViewerHeartbeat.ts</code>），两阶段策略（<code>seek-strategy.ts</code>）：</li></ul><table tabindex="0"><thead><tr><th>进度差</th><th>行为</th></tr></thead><tbody><tr><td>≤ 阈值 <code>max(3s, rate × 0.5)</code></td><td>忽略（收敛区）</td></tr><tr><td>阈值 &lt; diff ≤ <strong>6s</strong></td><td>软同步：倍速提到 <code>baseRate + 0.1</code>（封顶 2.0）渐进追赶</td></tr><tr><td>&gt; 6s</td><td>硬 seek 直接对齐</td></tr></tbody></table><p>seek 统一走 <code>executeSeek</code>（<code>seek-service.ts</code>）：目标落在缓冲区内或缺口不超过 10s 时走普通 seek；否则走 MSE Range seek（不重建 MediaSource，而是在锁内挂 <code>pendingSeekTargets</code> 接续）。seek 结束后补发合成 <code>seeked</code> 事件，保证外推基线新鲜。</p><h3 id="房主离线时由服务器接管" tabindex="-1">房主离线时由服务器接管 <a class="header-anchor" href="#房主离线时由服务器接管" aria-label="Permalink to &quot;房主离线时由服务器接管&quot;">​</a></h3><p><code>PlaybackBroadcasterService</code> 每 <strong>2s</strong> 遍历房间，仅当房主离线且房间内仍有 socket 时，按推算公式广播 <code>sync-heartbeat {source:&#39;server&#39;}</code>。观众端同时做 URL 过期检测，把 B站直链的过期签名去重后重新解析。房主重连有过渡期（<code>sharer-ready</code> 后首个心跳）：进度差 &gt; 10s 时提示「2 秒后自动同步」并延迟硬 seek，≤10s 走软同步，避免画面跳变。</p><h2 id="控制权申请" tabindex="-1">控制权申请 <a class="header-anchor" href="#控制权申请" aria-label="Permalink to &quot;控制权申请&quot;">​</a></h2><p>一起看模式下观众不能直接操作播放器，需申请审批：</p><ol><li>观众发起 <code>seek-request {roomId, time}</code> / <code>pause-request</code> / <code>play-request</code>，服务端校验在房且房主在线后转发。</li><li>房主端弹审批卡，12s 未处理自动关闭。开启<strong>自动通过</strong>时跳过弹窗直接执行。</li><li>房主同意后操作本地 video，走与普通操作相同的事件通道广播。申请者 pending 15s 未响应自动清除。</li><li>5s 窗口内，同目标 seek、同类 pause / play 的申请合并为一条（<code>viewerSocketIds</code> 数组）批量应答。</li></ol><p>顺序不可颠倒：房主同意 pause/play 时必须先操作本地 video 再应答，否则 video 已处于目标态、不再触发事件，观众端按钮状态不会更新。</p><h2 id="自主控制模式" tabindex="-1">自主控制模式 <a class="header-anchor" href="#自主控制模式" aria-label="Permalink to &quot;自主控制模式&quot;">​</a></h2><ul><li>判定：收到 <code>host-disconnected</code> 视为房主离线，<code>sharer-ready</code> 视为恢复。</li><li>效果：<code>canControl = isHost || hostOffline</code>。离线期间观众直接控制<strong>本地播放器</strong>（方向键 ±5s 等），不经服务器广播，避免多人操作冲突；服务器心跳在本地被屏蔽。</li><li>音乐侧：观众 7s 未收到 <code>music:host-heartbeat</code> 即判定房主离线，同样进入自主控制，见<a href="/advanced/music-pipeline">音乐管线</a>。</li></ul><h2 id="房间生命周期" tabindex="-1">房间生命周期 <a class="header-anchor" href="#房间生命周期" aria-label="Permalink to &quot;房间生命周期&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>参数</th><th>行为</th></tr></thead><tbody><tr><td>房主断线宽限期</td><td><strong>10 分钟</strong>（<code>HOST_RECONNECT_GRACE_MS</code>）</td><td>服务器维持最后状态继续外推，观众不中断；到期自动关房并广播 <code>room-closed</code></td></tr><tr><td>房主离线后加入宽限</td><td><strong>5 分钟</strong></td><td><code>getRecentSharer(roomId, 5min)</code> 允许观众进房；需审批的房间要求房主在线</td></tr><tr><td>无人自动清理</td><td>每 1 小时扫描，阈值 24 小时（可配）</td><td>受 <code>autoDeleteInactiveRooms</code> / <code>autoDeleteAfterHours</code> 控制，触发条件是 <code>lastAccessedAt</code> 超时</td></tr><tr><td>密码 / 审批</td><td>bcrypt(cost 10) / <code>requireApproval</code></td><td>root 免密；批准过的用户进白名单，永久免审批</td></tr></tbody></table><p>权限校验带 5s TTL 缓存（容量 1000，<code>room-permission.service.ts</code>），踢出、转交、会话结束时主动失效。管理员强制关房（HTTP 侧）时先广播 <code>room-closed</code> 再 disconnect 房间 socket，否则客户端会自动重连继续拉流。</p><h2 id="不走-socket-io-的实时能力" tabindex="-1">不走 Socket.IO 的实时能力 <a class="header-anchor" href="#不走-socket-io-的实时能力" aria-label="Permalink to &quot;不走 Socket.IO 的实时能力&quot;">​</a></h2><ul><li><strong>语音聊天</strong>：由独立 LiveKit 承载，主后端只签发凭证并执行禁言、踢出，见<a href="/advanced/voice">语音聊天链路</a>。</li><li><strong>OBS 推流</strong>：由内置媒体服务处理，播放端走 HTTP-FLV，不占 Socket.IO 通道。</li></ul><h2 id="观众端只读化与资源清理" tabindex="-1">观众端只读化与资源清理 <a class="header-anchor" href="#观众端只读化与资源清理" aria-label="Permalink to &quot;观众端只读化与资源清理&quot;">​</a></h2><ul><li><strong>只读守卫</strong>（<code>art-shared.ts</code> <code>installViewerGuards</code>，仅观众安装）：capture 阶段阻断 video click、大播放按钮 click，以及进度条的 pointerdown / mousedown / touchstart / click，使 ArtPlayer 本地控制失效。双击全屏由 <code>onVideoDblClick</code> 接管，对 <code>.zart-stage</code> 容器请求全屏（对 video 全屏会遮挡控制栏与弹幕层），iOS 降级为网页全屏。进度条点击转成 seek 申请。</li><li><strong>内嵌字幕提取取消</strong>：提取是一条独立于播放引擎的 Range 拉流。影片切换的 cleanup 中无条件 <code>clearTimeout</code> 与 <code>cancelEmbeddedExtraction()</code>，否则旧影片的提取流会继续经服务器中转。观众端同样本地提取内嵌字幕，seek 后字幕秒级可用，不依赖房主广播。</li></ul><h2 id="投屏-推流模式的对齐差异" tabindex="-1">投屏 / 推流模式的对齐差异 <a class="header-anchor" href="#投屏-推流模式的对齐差异" aria-label="Permalink to &quot;投屏 / 推流模式的对齐差异&quot;">​</a></h2><p><code>mode</code> 取值 <code>screen-share</code> / <code>watch-together</code> / <code>listen-together</code>。投屏模式下的 <code>shareMethod</code> 为 <code>webrtc</code> 或 <code>stream-push</code>，同步机制完全不同：</p><ul><li><strong>WebRTC</strong>：信令 <code>signal-offer/answer/ice-candidate</code> 定向转发，配合 <code>viewer-ready</code> / <code>sharer-ready</code> 握手，每个观众一条独立链路。</li><li><strong>OBS 推流</strong>：纯直播，无逐观众进度同步。「对齐」由 flv.js 追帧实现（<code>liveBufferLatencyChasing: true</code>，最大延迟 1.5s、目标 0.5s），多观众自动收敛到近实时。断流后指数退避重连（1s→16s，最多 5 次）；卡死检测（buffered 前沿停滞超 0.5s）时 seek 到 <code>bufferedEnd - 0.3</code>。推流码在 <code>postPublish</code> 校验：房间 active、投屏模式、stream-push 子模式三者需同时满足，否则 <code>session.reject()</code>。</li></ul><h2 id="常量速查" tabindex="-1">常量速查 <a class="header-anchor" href="#常量速查" aria-label="Permalink to &quot;常量速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>常量</th><th>值</th></tr></thead><tbody><tr><td>房主心跳间隔 / 超时判离线</td><td>5s / 15s（3 倍）</td></tr><tr><td>服务器心跳间隔</td><td>2s</td></tr><tr><td>进度广播等价阈值 / 软同步上限 / 跟随阈值</td><td>2s / 6s / max(3s, rate×0.5)</td></tr><tr><td>软同步追赶</td><td>+0.1 倍速，封顶 2.0</td></tr><tr><td>房主断线宽限 / 观众加入宽限</td><td>10min / 5min</td></tr><tr><td>无人清理</td><td>1h 周期 / 24h 阈值（可配）</td></tr><tr><td>权限缓存 TTL</td><td>5s</td></tr><tr><td>音乐心跳 / 离线判定 / 对齐阈值</td><td>2s / 7s / 2s</td></tr></tbody></table><p>取值对照 <code>sync-playback/constants.ts</code> 等文件。</p>',40)])])}const g=t(a,[["render",r]]);export{p as __pageData,g as default};
